# GENERATED by scripts/sync_hems_core.py from hems/core/hems/heater.py; do not edit here.
"""The water heater module (pure): plans the daily heating run and puts it in the base-load forecast.

The hot-water heat pump is the one big load that does not repeat at the same hour: it runs in the cheapest hour(s) of each
day. A median profile per hour of day therefore smears it (or, when the cheap hour is often the same, puts a peak at the
wrong place). This module plans the runs itself from the prices HEMS already holds, with the rule of the water heater add-on:
the cheapest window of the night part of the day (00-06; a light night program, 0 kWh unless set) and the cheapest window of the
day part (06-24; the heating, a longer one on the legionella weekday). It takes the heater out of the load history and puts the
planned runs back where they happen. It is a switchable HEMS module (`WaterHeaterConfig.enabled`) and, like the battery planner, it only plans: a
water heater add-on or automation still does the heating.
"""
from collections import defaultdict
from dataclasses import dataclass
from datetime import date, datetime, time, timedelta, timezone, tzinfo
from statistics import median
from typing import Sequence

from .prices import PriceSeries

QUARTER = timedelta(minutes=15)
MIN_HOURS_PER_DAY = 20                 # a local day with fewer hourly samples is left alone: its peak could be anything


HOUR = timedelta(hours=1)
NIGHT, HEATING, LEGIONELLA = "night", "heating", "legionella"
NIGHT_HOURS, DAY_HOURS = (0, 6), (6, 24)       # local hours of the night and day part: the same split as the water heater add-on


@dataclass(frozen=True)
class WaterHeaterConfig:
    """The water heater module's settings; the defaults are what was measured on this installation (a heating hour about 1.9 kWh, 2.6 kWh on the legionella day)."""
    enabled: bool = False
    energy_kwh: float = 1.9                  # electricity of one normal heating run (day part)
    hours: int = 1                           # length of a normal heating run, also of the night run
    night_energy_kwh: float = 0.0            # electricity of the night run; 0 = the day part carries the heating, no night run is planned
    legionella_energy_kwh: float = 2.6
    legionella_hours: int = 3
    legionella_weekday: int = 5              # 0 = Monday ... 5 = Saturday


@dataclass(frozen=True)
class HeatingRun:
    """A planned heating run: the energy it is expected to use, spread evenly over [start, end)."""
    start: datetime
    end: datetime
    energy_kwh: float
    kind: str = HEATING
    avg_price: float = 0.0                   # mean consumer import price over the run, EUR/kWh


def _hour_prices(prices: PriceSeries, tz: tzinfo) -> dict[datetime, float]:
    """Mean import price per hour (keyed by its UTC start), only for hours with all four quarters; `tz` only matters for zones with a half-hour offset."""
    quarters: dict[datetime, list[float]] = defaultdict(list)
    for start, price in zip(prices.starts, prices.import_eur_kwh):
        quarters[start.astimezone(tz).replace(minute=0, second=0, microsecond=0).astimezone(timezone.utc)].append(price)
    return {hour: sum(values) / len(values) for hour, values in quarters.items() if len(values) == 4}


def _local(day: date, hour: int, tz: tzinfo) -> datetime:
    """Wall-clock `hour` (0-24) of a local day; 24 is the next midnight."""
    return datetime.combine(day + timedelta(days=hour // 24), time(hour % 24), tz)


def _cheapest_window(hours: dict[datetime, float], part_start: datetime, part_end: datetime, length: int) -> tuple[datetime, float] | None:
    """The start (UTC) and mean price of the cheapest `length` consecutive hours inside [part_start, part_end); the earliest of equals; None unless every hour of the part has a price.

    A partly known part would pick the cheapest of what is left, which is not what the heater does (it chose over the whole part).
    Hours are counted in UTC, so a part of a 23 or 25 hour day (clock change) has the hours it really has."""
    first = part_start.astimezone(timezone.utc)
    part_hours = [first + k * HOUR for k in range((part_end.astimezone(timezone.utc) - first) // HOUR)]
    if length > len(part_hours) or any(h not in hours for h in part_hours):
        return None
    costs = [(sum(hours[h] for h in part_hours[i:i + length]) / length, part_hours[i]) for i in range(len(part_hours) - length + 1)]
    price, start = min(costs)
    return start, price


LEGIONELLA_INTERVAL_DAYS = 7
LEGIONELLA_SLACK_DAYS = 1                 # the alert waits one day past the due day before it calls the run overdue


def legionella_due_date(last_run: datetime | None, tz: tzinfo, interval_days: int = LEGIONELLA_INTERVAL_DAYS) -> date | None:
    """The first local calendar day the protection is due again, None when no run is known (due at once).

    Calendar days, not elapsed hours: the water heater add-on counted `(now - last).days` and skipped Saturday 24 Oct 2026 because the
    run of the 17th was stamped at 18:30 and the next window opened at 14:00 (6 days 19.5 h). Same rule as the add-on's 1.3.1 fix."""
    return None if last_run is None else last_run.astimezone(tz).date() + timedelta(days=interval_days)


def legionella_due(last_run: datetime | None, day: date, tz: tzinfo, interval_days: int = LEGIONELLA_INTERVAL_DAYS) -> bool:
    """Whether the protection is due on `day`: no run known, or `interval_days` calendar days after the day of the last run."""
    due = legionella_due_date(last_run, tz, interval_days)
    return due is None or due <= day


def legionella_overdue(last_run: datetime | None, today: date, tz: tzinfo) -> bool:
    """True when the due day passed more than LEGIONELLA_SLACK_DAYS ago without a run; False when no run is known (nothing to compare)."""
    due = legionella_due_date(last_run, tz)
    return due is not None and today > due + timedelta(days=LEGIONELLA_SLACK_DAYS)


def plan_runs(prices: PriceSeries, now: datetime, config: WaterHeaterConfig, tz: tzinfo,
              last_legionella: datetime | None = None) -> list[HeatingRun]:
    """The planned runs (times in UTC) from `now` on, in order: per local day with a complete price curve a night run (if it has energy) and a day run.

    The day run is the cheapest window of 06-24, the legionella one (longer, more energy) on its weekday; the night run the cheapest
    window of 00-06. Empty when the module is off. A run that has ended is left out; one that is going on stays.

    The legionella run is planned only on its weekday and only when it is due (`legionella_due`), as the add-on does; there is no
    catch-up on another day (Mark's choice). Without a known last run it is planned (due at once: the safe side)."""
    if not config.enabled:
        return []
    hours = _hour_prices(prices, tz)
    runs: list[HeatingRun] = []
    for day in sorted({h.astimezone(tz).date() for h in hours}):
        legionella = day.weekday() == config.legionella_weekday and legionella_due(last_legionella, day, tz)
        parts = ((NIGHT, NIGHT_HOURS, config.hours, config.night_energy_kwh),
                 (LEGIONELLA if legionella else HEATING, DAY_HOURS, config.legionella_hours if legionella else config.hours,
                  config.legionella_energy_kwh if legionella else config.energy_kwh))
        for kind, (from_hour, to_hour), length, energy in parts:
            found = _cheapest_window(hours, _local(day, from_hour, tz), _local(day, to_hour, tz), length) if energy > 0 else None
            if found and found[0] + length * HOUR > now:
                runs.append(HeatingRun(found[0], found[0] + length * HOUR, energy, kind, found[1]))
    return runs


def run_kwh_per_quarter(runs: Sequence[HeatingRun]) -> dict[datetime, float]:
    """kWh per quarter start (UTC) of the planned runs: each run's energy spread evenly over the quarters it covers."""
    per_quarter: dict[datetime, float] = defaultdict(float)
    for run in runs:
        quarters = max(round((run.end - run.start) / QUARTER), 1)
        for k in range(quarters):
            per_quarter[(run.start + k * QUARTER).astimezone(timezone.utc)] += run.energy_kwh / quarters
    return dict(per_quarter)


def without_daily_peak(history: Sequence[tuple[datetime, float]], cap_kwh: float, tz: tzinfo) -> list[tuple[datetime, float]]:
    """The hourly load history with each day's heater removed: the day's highest hour loses what it has above the day's median, at most `cap_kwh`.

    The heater is the largest load of the day (1.7-3.4 kWh above the median on every recorded day of 7-15 Oct 2026), so the
    day's peak hour is where it ran. Days without about a full set of hours are left as they are."""
    if cap_kwh <= 0:
        return list(history)
    days: dict = defaultdict(list)
    for index, (ts, _) in enumerate(history):
        days[ts.astimezone(tz).date()].append(index)
    cleaned = list(history)
    for indexes in days.values():
        if len(indexes) < MIN_HOURS_PER_DAY:
            continue
        peak = max(indexes, key=lambda i: history[i][1])
        excess_kwh = (history[peak][1] - median(history[i][1] for i in indexes)) / 1000
        cleaned[peak] = (history[peak][0], history[peak][1] - 1000 * min(cap_kwh, max(excess_kwh, 0.0)))
    return cleaned
